import { Color, mard221Colors } from '../data/colors';
import { findClosestColor, rgbToLab, ciede2000 } from './colorUtils';

export interface Pixel {
  r: number;
  g: number;
  b: number;
  a: number;
}

export interface RGB {
  r: number;
  g: number;
  b: number;
}

export function loadImage(src: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => resolve(img);
    img.onerror = reject;
    img.src = src;
  });
}

function getLuminance(r: number, g: number, b: number): number {
  return 0.299 * r + 0.587 * g + 0.114 * b;
}

function rgbToGrayscale(r: number, g: number, b: number): number {
  return Math.round(getLuminance(r, g, b));
}

function applyBilateralFilter(
  pixels: Pixel[][],
  width: number,
  height: number,
  sigmaSpatial: number = 2,
  sigmaRange: number = 30
): Pixel[][] {
  const output: Pixel[][] = [];
  const halfSize = Math.ceil(sigmaSpatial * 3);
  
  for (let y = 0; y < height; y++) {
    output[y] = [];
    for (let x = 0; x < width; x++) {
      let sumR = 0, sumG = 0, sumB = 0;
      let sumWeight = 0;
      
      for (let dy = -halfSize; dy <= halfSize; dy++) {
        for (let dx = -halfSize; dx <= halfSize; dx++) {
          const nx = x + dx;
          const ny = y + dy;
          
          if (nx >= 0 && nx < width && ny >= 0 && ny < height) {
            const currentPixel = pixels[y][x];
            const neighborPixel = pixels[ny][nx];
            
            const spatialDist = Math.sqrt(dx * dx + dy * dy);
            const rangeDist = Math.sqrt(
              Math.pow(currentPixel.r - neighborPixel.r, 2) +
              Math.pow(currentPixel.g - neighborPixel.g, 2) +
              Math.pow(currentPixel.b - neighborPixel.b, 2)
            );
            
            const spatialWeight = Math.exp(-(spatialDist * spatialDist) / (2 * sigmaSpatial * sigmaSpatial));
            const rangeWeight = Math.exp(-(rangeDist * rangeDist) / (2 * sigmaRange * sigmaRange));
            const weight = spatialWeight * rangeWeight;
            
            sumR += neighborPixel.r * weight;
            sumG += neighborPixel.g * weight;
            sumB += neighborPixel.b * weight;
            sumWeight += weight;
          }
        }
      }
      
      output[y][x] = {
        r: Math.round(sumR / sumWeight),
        g: Math.round(sumG / sumWeight),
        b: Math.round(sumB / sumWeight),
        a: pixels[y][x].a
      };
    }
  }
  
  return output;
}

interface KMeansResult {
  clusters: RGB[];
  labels: number[];
}

function kMeans(pixels: RGB[], k: number, maxIterations: number = 50): KMeansResult {
  const n = pixels.length;
  const labels: number[] = new Array(n).fill(0);
  
  const centers = pixels
    .map((p, i) => ({ pixel: p, index: i }))
    .sort(() => Math.random() - 0.5)
    .slice(0, k)
    .map(p => p.pixel);
  
  for (let iter = 0; iter < maxIterations; iter++) {
    for (let i = 0; i < n; i++) {
      let minDist = Infinity;
      let minIdx = 0;
      
      for (let j = 0; j < k; j++) {
        const dist = Math.sqrt(
          Math.pow(pixels[i].r - centers[j].r, 2) +
          Math.pow(pixels[i].g - centers[j].g, 2) +
          Math.pow(pixels[i].b - centers[j].b, 2)
        );
        
        if (dist < minDist) {
          minDist = dist;
          minIdx = j;
        }
      }
      
      labels[i] = minIdx;
    }
    
    const newCenters: RGB[] = new Array(k).fill(null).map(() => ({ r: 0, g: 0, b: 0 }));
    const counts: number[] = new Array(k).fill(0);
    
    for (let i = 0; i < n; i++) {
      const cluster = labels[i];
      newCenters[cluster].r += pixels[i].r;
      newCenters[cluster].g += pixels[i].g;
      newCenters[cluster].b += pixels[i].b;
      counts[cluster]++;
    }
    
    for (let j = 0; j < k; j++) {
      if (counts[j] > 0) {
        newCenters[j].r = Math.round(newCenters[j].r / counts[j]);
        newCenters[j].g = Math.round(newCenters[j].g / counts[j]);
        newCenters[j].b = Math.round(newCenters[j].b / counts[j]);
      }
    }
    
    let changed = false;
    for (let j = 0; j < k; j++) {
      const dist = Math.sqrt(
        Math.pow(centers[j].r - newCenters[j].r, 2) +
        Math.pow(centers[j].g - newCenters[j].g, 2) +
        Math.pow(centers[j].b - newCenters[j].b, 2)
      );
      
      if (dist > 0.5) {
        changed = true;
        break;
      }
    }
    
    centers.splice(0, k, ...newCenters);
    
    if (!changed) break;
  }
  
  return { clusters: centers, labels };
}

function quantizeColors(pixels: Pixel[][], width: number, height: number, maxColors: number): RGB[][] {
  const rgbPixels: RGB[] = [];
  
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (pixels[y][x].a >= 128) {
        rgbPixels.push({
          r: pixels[y][x].r,
          g: pixels[y][x].g,
          b: pixels[y][x].b
        });
      }
    }
  }
  
  if (rgbPixels.length <= maxColors) {
    const result: RGB[][] = [];
    for (let y = 0; y < height; y++) {
      result[y] = [];
      for (let x = 0; x < width; x++) {
        if (pixels[y][x].a >= 128) {
          result[y][x] = { r: pixels[y][x].r, g: pixels[y][x].g, b: pixels[y][x].b };
        } else {
          result[y][x] = { r: 255, g: 255, b: 255 };
        }
      }
    }
    return result;
  }
  
  const { clusters, labels } = kMeans(rgbPixels, maxColors);
  
  const result: RGB[][] = [];
  let idx = 0;
  
  for (let y = 0; y < height; y++) {
    result[y] = [];
    for (let x = 0; x < width; x++) {
      if (pixels[y][x].a >= 128) {
        result[y][x] = clusters[labels[idx++]];
      } else {
        result[y][x] = { r: 255, g: 255, b: 255 };
      }
    }
  }
  
  return result;
}

function recoverFeatures(
  grid: string[][],
  rgbGrid: RGB[][],
  originalPixels: Pixel[][],
  originalWidth: number,
  originalHeight: number,
  targetWidth: number,
  targetHeight: number
): { grid: string[][]; rgbGrid: RGB[][] } {
  const newGrid = grid.map(row => [...row]);
  const newRgbGrid = rgbGrid.map(row => row.map(p => ({ ...p })));
  
  const scaleX = originalWidth / targetWidth;
  const scaleY = originalHeight / targetHeight;
  
  for (let ty = 0; ty < targetHeight; ty++) {
    for (let tx = 0; tx < targetWidth; tx++) {
      const currentRgb = rgbGrid[ty][tx];
      const currentLum = getLuminance(currentRgb.r, currentRgb.g, currentRgb.b);
      
      const startX = Math.floor(tx * scaleX);
      const endX = Math.min(Math.floor((tx + 1) * scaleX), originalWidth);
      const startY = Math.floor(ty * scaleY);
      const endY = Math.min(Math.floor((ty + 1) * scaleY), originalHeight);
      
      let minLum = 255;
      let maxLum = 0;
      let minPixel: Pixel | null = null;
      let maxPixel: Pixel | null = null;
      let totalPixels = 0;
      
      for (let py = startY; py < endY; py++) {
        for (let px = startX; px < endX; px++) {
          const pixel = originalPixels[py][px];
          if (pixel.a >= 128) {
            totalPixels++;
            const pixelLum = getLuminance(pixel.r, pixel.g, pixel.b);
            
            if (pixelLum < minLum) {
              minLum = pixelLum;
              minPixel = pixel;
            }
            if (pixelLum > maxLum) {
              maxLum = pixelLum;
              maxPixel = pixel;
            }
          }
        }
      }
      
      if (totalPixels > 0 && maxLum - minLum > 40) {
        if (minPixel && currentLum - minLum > 30) {
          const recoveredRgb = { r: minPixel.r, g: minPixel.g, b: minPixel.b };
          const closestColor = findClosestColor(recoveredRgb);
          newGrid[ty][tx] = closestColor.id;
          newRgbGrid[ty][tx] = recoveredRgb;
        } else if (maxPixel && maxLum - currentLum > 30) {
          const recoveredRgb = { r: maxPixel.r, g: maxPixel.g, b: maxPixel.b };
          const closestColor = findClosestColor(recoveredRgb);
          newGrid[ty][tx] = closestColor.id;
          newRgbGrid[ty][tx] = recoveredRgb;
        }
      }
    }
  }
  
  return { grid: newGrid, rgbGrid: newRgbGrid };
}

export function pixelateImage(
  img: HTMLImageElement,
  targetSize: number,
  removeBackground: boolean = false
): { grid: string[][]; rgbGrid: RGB[][] } {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Failed to get canvas context');

  const aspectRatio = img.width / img.height;
  let targetWidth = targetSize;
  let targetHeight = targetSize;

  if (aspectRatio > 1) {
    targetHeight = Math.round(targetSize / aspectRatio);
  } else {
    targetWidth = Math.round(targetSize * aspectRatio);
  }

  const superSampleSize = 104;
  let superWidth = superSampleSize;
  let superHeight = superSampleSize;
  
  if (aspectRatio > 1) {
    superHeight = Math.round(superSampleSize / aspectRatio);
  } else {
    superWidth = Math.round(superSampleSize * aspectRatio);
  }

  canvas.width = img.width;
  canvas.height = img.height;
  ctx.drawImage(img, 0, 0);
  
  const originalImageData = ctx.getImageData(0, 0, img.width, img.height);
  const originalPixels: Pixel[][] = [];
  
  for (let y = 0; y < img.height; y++) {
    const row: Pixel[] = [];
    for (let x = 0; x < img.width; x++) {
      const i = (y * img.width + x) * 4;
      row.push({
        r: originalImageData.data[i],
        g: originalImageData.data[i + 1],
        b: originalImageData.data[i + 2],
        a: originalImageData.data[i + 3],
      });
    }
    originalPixels.push(row);
  }

  if (removeBackground) {
    removeImageBackground(originalPixels);
  }

  const targetCanvas = document.createElement('canvas');
  const targetCtx = targetCanvas.getContext('2d');
  if (!targetCtx) throw new Error('Failed to get canvas context');
  
  targetCanvas.width = superWidth;
  targetCanvas.height = superHeight;
  targetCtx.imageSmoothingEnabled = true;
  targetCtx.imageSmoothingQuality = 'high';
  
  targetCtx.drawImage(img, 0, 0, superWidth, superHeight);
  
  const targetImageData = targetCtx.getImageData(0, 0, superWidth, superHeight);
  
  const grid: string[][] = [];
  const rgbGrid: RGB[][] = [];

  for (let y = 0; y < superHeight; y++) {
    const row: string[] = [];
    const rgbRow: RGB[] = [];
    
    for (let x = 0; x < superWidth; x++) {
      const i = (y * superWidth + x) * 4;
      const r = targetImageData.data[i];
      const g = targetImageData.data[i + 1];
      const b = targetImageData.data[i + 2];
      const a = targetImageData.data[i + 3];
      
      if (a < 128) {
        row.push('H1');
        rgbRow.push({ r: 255, g: 255, b: 255 });
        continue;
      }
      
      const rgb = { r, g, b };
      rgbRow.push(rgb);
      
      const closestColor = findClosestColor(rgb);
      row.push(closestColor.id);
    }
    grid.push(row);
    rgbGrid.push(rgbRow);
  }

  const recovered = recoverFeatures(grid, rgbGrid, originalPixels, img.width, img.height, superWidth, superHeight);

  if (targetWidth === superWidth && targetHeight === superHeight) {
    return recovered;
  }

  const scaleX = superWidth / targetWidth;
  const scaleY = superHeight / targetHeight;
  
  const finalGrid: string[][] = [];
  const finalRgbGrid: RGB[][] = [];
  
  for (let ty = 0; ty < targetHeight; ty++) {
    const row: string[] = [];
    const rgbRow: RGB[] = [];
    
    for (let tx = 0; tx < targetWidth; tx++) {
      const startX = Math.floor(tx * scaleX);
      const endX = Math.min(Math.floor((tx + 1) * scaleX), superWidth);
      const startY = Math.floor(ty * scaleY);
      const endY = Math.min(Math.floor((ty + 1) * scaleY), superHeight);
      
      const colorCount: Record<string, number> = {};
      const rgbSum: Record<string, { r: number; g: number; b: number; count: number }> = {};
      
      let totalPixels = 0;
      
      for (let sy = startY; sy < endY; sy++) {
        for (let sx = startX; sx < endX; sx++) {
          const colorId = recovered.grid[sy][sx];
          const rgb = recovered.rgbGrid[sy][sx];
          
          colorCount[colorId] = (colorCount[colorId] || 0) + 1;
          
          if (!rgbSum[colorId]) {
            rgbSum[colorId] = { r: 0, g: 0, b: 0, count: 0 };
          }
          rgbSum[colorId].r += rgb.r;
          rgbSum[colorId].g += rgb.g;
          rgbSum[colorId].b += rgb.b;
          rgbSum[colorId].count++;
          
          totalPixels++;
        }
      }
      
      let selectedColor = 'H1';
      let maxCount = 0;
      
      for (const [colorId, count] of Object.entries(colorCount)) {
        if (count > maxCount) {
          maxCount = count;
          selectedColor = colorId;
        } else if (count === maxCount) {
          const currentLum = getLuminance(
            rgbSum[selectedColor].r / rgbSum[selectedColor].count,
            rgbSum[selectedColor].g / rgbSum[selectedColor].count,
            rgbSum[selectedColor].b / rgbSum[selectedColor].count
          );
          const newLum = getLuminance(
            rgbSum[colorId].r / rgbSum[colorId].count,
            rgbSum[colorId].g / rgbSum[colorId].count,
            rgbSum[colorId].b / rgbSum[colorId].count
          );
          
          if (Math.abs(currentLum - 128) < Math.abs(newLum - 128)) {
            selectedColor = colorId;
          }
        }
      }
      
      const avgRgb = rgbSum[selectedColor];
      row.push(selectedColor);
      rgbRow.push({ 
        r: Math.round(avgRgb.r / avgRgb.count), 
        g: Math.round(avgRgb.g / avgRgb.count), 
        b: Math.round(avgRgb.b / avgRgb.count) 
      });
    }
    
    finalGrid.push(row);
    finalRgbGrid.push(rgbRow);
  }
  
  return { grid: finalGrid, rgbGrid: finalRgbGrid };
}

function removeImageBackground(pixels: Pixel[][]): void {
  const width = pixels[0]?.length || 0;
  const height = pixels.length;
  
  if (width === 0 || height === 0) return;

  const edgePixels: Pixel[] = [];
  
  for (let x = 0; x < width; x++) {
    edgePixels.push(pixels[0][x]);
    edgePixels.push(pixels[height - 1][x]);
  }
  
  for (let y = 1; y < height - 1; y++) {
    edgePixels.push(pixels[y][0]);
    edgePixels.push(pixels[y][width - 1]);
  }

  const avgR = edgePixels.reduce((sum, p) => sum + p.r, 0) / edgePixels.length;
  const avgG = edgePixels.reduce((sum, p) => sum + p.g, 0) / edgePixels.length;
  const avgB = edgePixels.reduce((sum, p) => sum + p.b, 0) / edgePixels.length;

  const tolerance = 50;

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const pixel = pixels[y][x];
      const diffR = Math.abs(pixel.r - avgR);
      const diffG = Math.abs(pixel.g - avgG);
      const diffB = Math.abs(pixel.b - avgB);

      if (diffR < tolerance && diffG < tolerance && diffB < tolerance) {
        pixel.a = 0;
      }
    }
  }
}

export function applyDithering(grid: string[][], rgbGrid: RGB[][]): string[][] {
  const width = grid[0]?.length || 0;
  const height = grid.length;
  
  if (width === 0 || height === 0) return grid;

  const floatGrid: { r: number; g: number; b: number }[][] = rgbGrid.map(row =>
    row.map(p => ({ ...p }))
  );

  const newGrid = grid.map(row => [...row]);
  
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const original = floatGrid[y][x];
      
      const clampedR = Math.max(0, Math.min(255, Math.round(original.r)));
      const clampedG = Math.max(0, Math.min(255, Math.round(original.g)));
      const clampedB = Math.max(0, Math.min(255, Math.round(original.b)));

      const closestColor = findClosestColor({ r: clampedR, g: clampedG, b: clampedB });
      newGrid[y][x] = closestColor.id;

      const errorR = original.r - closestColor.rgb.r;
      const errorG = original.g - closestColor.rgb.g;
      const errorB = original.b - closestColor.rgb.b;

      if (x < width - 1) {
        floatGrid[y][x + 1].r += errorR * 7 / 16;
        floatGrid[y][x + 1].g += errorG * 7 / 16;
        floatGrid[y][x + 1].b += errorB * 7 / 16;
      }
      if (y < height - 1) {
        floatGrid[y + 1][x].r += errorR * 5 / 16;
        floatGrid[y + 1][x].g += errorG * 5 / 16;
        floatGrid[y + 1][x].b += errorB * 5 / 16;
        
        if (x > 0) {
          floatGrid[y + 1][x - 1].r += errorR * 3 / 16;
          floatGrid[y + 1][x - 1].g += errorG * 3 / 16;
          floatGrid[y + 1][x - 1].b += errorB * 3 / 16;
        }
        if (x < width - 1) {
          floatGrid[y + 1][x + 1].r += errorR * 1 / 16;
          floatGrid[y + 1][x + 1].g += errorG * 1 / 16;
          floatGrid[y + 1][x + 1].b += errorB * 1 / 16;
        }
      }
    }
  }

  return newGrid;
}

export function compressColors(grid: string[][], maxColors: number): string[][] {
  if (maxColors <= 0) return grid;

  const colorCounts: Record<string, number> = {};
  
  for (const row of grid) {
    for (const colorId of row) {
      colorCounts[colorId] = (colorCounts[colorId] || 0) + 1;
    }
  }

  const sortedColors = Object.entries(colorCounts)
    .sort((a, b) => b[1] - a[1]);

  const topColors = sortedColors.slice(0, maxColors).map(([id]) => id);

  if (topColors.length === 0) return grid;

  const newGrid = grid.map(row => 
    row.map(colorId => {
      if (topColors.includes(colorId)) {
        return colorId;
      }

      const originalColor = mard221Colors.find(c => c.id === colorId);
      if (!originalColor) return topColors[0];

      let closestColor = topColors[0];
      let minDistance = Infinity;

      for (const topId of topColors) {
        const topColor = mard221Colors.find(c => c.id === topId);
        if (!topColor) continue;

        const distance = Math.sqrt(
          Math.pow(originalColor.rgb.r - topColor.rgb.r, 2) +
          Math.pow(originalColor.rgb.g - topColor.rgb.g, 2) +
          Math.pow(originalColor.rgb.b - topColor.rgb.b, 2)
        );

        if (distance < minDistance) {
          minDistance = distance;
          closestColor = topId;
        }
      }

      return closestColor;
    })
  );

  return newGrid;
}
